    r DEL mystream
    for {set j 1} {$j < 1001} {incr j} {
        set minid 1000
        if {$j >= 5} {
            set minid [expr {$j-5}]
        }
        if {rand() < 0.9} {
            r XADD mystream MINID $minid $j xitem $j
        } else {
